"""Tensor-parallel linear layers (column / row parallel) in PyTorch.

The layers rely only on the public ``torch.distributed`` API and degrade
gracefully to single-process behaviour when distributed is unavailable or
uninitialized (world_size == 1).
"""

import torch
import torch.distributed as dist
import torch.nn.functional as F


# --------------------------------------------------------------------------- #
# distributed helpers
# --------------------------------------------------------------------------- #
def _is_distributed():
    try:
        return dist.is_available() and dist.is_initialized()
    except Exception:
        return False


def get_world_size():
    if _is_distributed():
        return dist.get_world_size()
    return 1


def get_rank():
    if _is_distributed():
        return dist.get_rank()
    return 0


def _split_tensor(tensor, dim, world_size, rank):
    """Return the ``rank``-th of ``world_size`` equal chunks along ``dim``."""
    if world_size == 1:
        return tensor
    size = tensor.size(dim)
    assert size % world_size == 0, (
        "dimension %d of size %d is not divisible by world size %d"
        % (dim, size, world_size)
    )
    per_rank = size // world_size
    return tensor.narrow(dim, rank * per_rank, per_rank)


def _all_reduce(tensor):
    if get_world_size() == 1:
        return tensor
    tensor = tensor.contiguous()
    dist.all_reduce(tensor)
    return tensor


def _all_gather_last_dim(tensor):
    world_size = get_world_size()
    if world_size == 1:
        return tensor
    tensor = tensor.contiguous()
    gathered = [torch.empty_like(tensor) for _ in range(world_size)]
    dist.all_gather(gathered, tensor)
    gathered[get_rank()] = tensor
    return torch.cat(gathered, dim=-1)


class _CopyToModelParallelRegion(torch.autograd.Function):
    """Identity forward, all-reduce of the gradient in backward."""

    @staticmethod
    def forward(ctx, input_):
        return input_

    @staticmethod
    def backward(ctx, grad_output):
        return _all_reduce(grad_output.clone())


class _ReduceFromModelParallelRegion(torch.autograd.Function):
    """All-reduce forward, identity backward."""

    @staticmethod
    def forward(ctx, input_):
        return _all_reduce(input_.clone())

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class _GatherFromModelParallelRegion(torch.autograd.Function):
    """All-gather along the last dimension forward, split in backward."""

    @staticmethod
    def forward(ctx, input_):
        return _all_gather_last_dim(input_)

    @staticmethod
    def backward(ctx, grad_output):
        world_size = get_world_size()
        if world_size == 1:
            return grad_output
        return _split_tensor(
            grad_output, -1, world_size, get_rank()
        ).contiguous()


def copy_to_model_parallel_region(input_):
    return _CopyToModelParallelRegion.apply(input_)


def reduce_from_model_parallel_region(input_):
    return _ReduceFromModelParallelRegion.apply(input_)


def gather_from_model_parallel_region(input_):
    return _GatherFromModelParallelRegion.apply(input_)


# --------------------------------------------------------------------------- #
# layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(torch.nn.Module):
    """Linear layer with the weight matrix split along its columns.

    ``y = x A + b`` where ``A`` is partitioned along its column (output)
    dimension: ``A = [A_0, ..., A_{p-1}]``.  Each rank stores
    ``weight`` of shape ``(out_features // world_size, in_features)``
    (``torch.nn.Linear`` layout) and the matching bias shard.  The outputs of
    every rank are concatenated along the last dimension (all_gather).
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = get_world_size()
        rank = get_rank()
        self.world_size = world_size
        self.rank = rank

        assert out_features % world_size == 0, (
            "out_features (%d) must be divisible by world size (%d)"
            % (out_features, world_size)
        )
        self.output_size_per_partition = out_features // world_size

        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            torch.nn.init.xavier_normal_(master_weight)
        master_weight = torch.as_tensor(master_weight)

        weight_shard = _split_tensor(
            master_weight.detach(), 0, world_size, rank
        ).clone().contiguous()
        self.weight = torch.nn.Parameter(weight_shard)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # identity forward / all-reduce backward: the input is replicated.
        input_parallel = copy_to_model_parallel_region(input_)
        output_parallel = F.linear(input_parallel, self.weight, self.bias)
        # all_gather the partial outputs along the last dimension.
        return gather_from_model_parallel_region(output_parallel)

    def extra_repr(self):
        return "in_features=%d, out_features=%d, bias=%s" % (
            self.in_features,
            self.out_features,
            self.bias is not None,
        )


class RowParallelLinear(torch.nn.Module):
    """Linear layer with the weight matrix split along its rows.

    ``y = x A + b`` where ``A`` is partitioned along its row (input)
    dimension.  ``forward()`` receives only this rank's slice of the input
    (already scattered along the last dimension); the partial results are
    summed across ranks (all_reduce) and the full bias is added afterwards.
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = get_world_size()
        rank = get_rank()
        self.world_size = world_size
        self.rank = rank

        assert in_features % world_size == 0, (
            "in_features (%d) must be divisible by world size (%d)"
            % (in_features, world_size)
        )
        self.input_size_per_partition = in_features // world_size

        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            torch.nn.init.xavier_normal_(master_weight)
        master_weight = torch.as_tensor(master_weight)

        # nn.Linear layout is (out_features, in_features): the row split of the
        # mathematical matrix A corresponds to dim 1 here.
        weight_shard = _split_tensor(
            master_weight.detach(), 1, world_size, rank
        ).clone().contiguous()
        self.weight = torch.nn.Parameter(weight_shard)

        if bias:
            # bias is not sharded: full size, replicated on every rank.
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # input_ is already the local shard along the last dimension.
        output_parallel = F.linear(input_, self.weight)
        # all_reduce forward / identity backward.
        output = reduce_from_model_parallel_region(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output

    def extra_repr(self):
        return "in_features=%d, out_features=%d, bias=%s" % (
            self.in_features,
            self.out_features,
            self.bias is not None,
        )

